Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-containsduplicateiii":{"key":"topic-containsduplicateiii","number":null,"title":"Contains Duplicate III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Contains Duplicate III.py","code":"class Solution:\n    def containsNearbyAlmostDuplicate(self, nums: List[int], k: int, t: int) -> bool:\n        def getBucketId(num, width):\n            return num // width\n        if t < 0 or k < 0:\n            return False\n        dictionary = {}\n        width = t + 1\n        for i, num in enumerate(nums):\n            key = getBucketId(num, width)\n            if key in dictionary:\n                return True\n            if key - 1 in dictionary and abs(num - dictionary[key - 1]) < width:\n                return True\n            if key + 1 in dictionary and abs(num - dictionary[key + 1]) < width:\n                return True\n            dictionary[key] = num\n            if i >= k:\n                dictionary.pop(getBucketId(nums[i - k], width))\n        return False","hash":"e9b8b2c2f85c502b34fb6e0f7dac06df65713487efbef1ddb07c862180b3105d","origins":[{"source":"solutions","path":"Binary Search Tree/Contains Duplicate III.py"},{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Contains Duplicate III.py"}]}],"sources":["solutions"]},"topic-contiguousarray":{"key":"topic-contiguousarray","number":null,"title":"Contiguous Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Contiguous Array.py","code":"class Solution:\n    def findMaxLength(self, nums: List[int]) -> int:\n        hashMap, maxLen, count = {0: -1}, 0, 0\n        for i in range(len(nums)):\n            count += (-1 if nums[i] == 0 else 1)\n            if count in hashMap:\n                maxLen = max(maxLen, i - hashMap[count])\n            else:\n                hashMap[count] = i\n        return maxLen","hash":"6c3a358dbd59293dc88f546cd62e23a7bd2367dc1870f3a7d9ed8e2001bf56f0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Contiguous Array.py"}]}],"sources":["solutions"]},"topic-convertanumbertohexadecimal":{"key":"topic-convertanumbertohexadecimal","number":null,"title":"Convert a Number to Hexadecimal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Convert a Number to Hexadecimal.py","code":"class Solution:\n    def toHex(self, num: int) -> str:\n        if num == 0:\n            return '0'\n        chars, result = '0123456789abcdef', []\n        if num < 0:\n            num += (1 << 32)\n        while num > 0:\n            result.insert(0, chars[num % 16])\n            num //= 16\n        return ''.join(result)","hash":"a4db717045b9ba381f3a6fc142cb6fc38d97e325350ed1d0a88924cb01657859","origins":[{"source":"solutions","path":"Convert a Number to Hexadecimal.py"}]}],"sources":["solutions"]},"topic-convertbinarynumberinalinkedlisttointeger":{"key":"topic-convertbinarynumberinalinkedlisttointeger","number":null,"title":"Convert Binary Number in a Linked List to Integer","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Convert Binary Number in a Linked List to Integer.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def getDecimalValue(self, head: ListNode) -> int:\n        result = head.val\n        while head.next:\n            result = result << 1\n            head = head.next\n            result = result | head.val\n        return result","hash":"61e773838adbbb7d469431a162b711c7277400e2c047c76f3bb87eac9df18906","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Convert Binary Number in a Linked List to Integer.py"}]}],"sources":["solutions"]},"topic-convertbsttogreatertree":{"key":"topic-convertbsttogreatertree","number":null,"title":"Convert BST to Greater Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Convert BST to Greater Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def __init__(self):\n        self.total = 0\n\n    def convertBST(self, root: Optional[TreeNode]) -> Optional[TreeNode]:\n        if root is not None:\n            self.convertBST(root.right)\n            self.total += root.val\n            root.val = self.total\n            self.convertBST(root.left)\n        return root","hash":"b01d320ea7aafd6ee8357159ba453bd1a2edd7595a330916fa369858ba46145c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/Convert BST to Greater Tree.py"}]}],"sources":["solutions"]},"topic-convertintegertothesumoftwonozerointegers":{"key":"topic-convertintegertothesumoftwonozerointegers","number":null,"title":"Convert Integer to the Sum of Two No Zero Integers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Convert Integer to the Sum of Two No-Zero Integers.py","code":"class Solution:\n    def getNoZeroIntegers(self, n: int) -> List[int]:\n        for i in range(1, n + 1):\n            complement = n - i\n            if '0' not in set(str(i)) and '0' not in set(str(complement)):\n                return [i, complement]","hash":"0c3ec29d758abbb3ef2034eebc23d663f1d93b04dd2d961fa20b51d519cc2004","origins":[{"source":"solutions","path":"Convert Integer to the Sum of Two No-Zero Integers.py"}]}],"sources":["solutions"]},"topic-converttobase2":{"key":"topic-converttobase2","number":null,"title":"Convert to Base 2","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Convert to Base -2.py","code":"class Solution:\n    def baseNeg2(self, N: int) -> str:\n        result = []\n        while N:\n            r = N % -2\n            if r == -1:\n                r = 1\n            result.append(str(r))\n            N = (N - r) // (-2)\n        return ''.join(result[::-1]) or '0'","hash":"2aa586c1b5bd694c0c5d4eb89e0153038e82540f7fa13920f2da0404382b70d0","origins":[{"source":"solutions","path":"Convert to Base -2.py"}]}],"sources":["solutions"]},"topic-coordinatewithmaximumnetworkquality":{"key":"topic-coordinatewithmaximumnetworkquality","number":null,"title":"Coordinate With Maximum Network Quality","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Coordinate With Maximum Network Quality.py","code":"class Solution:\n    def bestCoordinate(self, towers: List[List[int]], radius: int) -> List[int]:\n        \n        def getNetworkQuality(pointX, pointY):\n            quality = 0\n            for x, y, q in towers:\n                distance = math.dist((x, y), (pointX, pointY))\n                if distance <= radius:\n                    quality += int(q / (1 + distance))\n            return quality\n        \n        maxQuality, result = float('-inf'), [0, 0]\n        for x in range(51):\n            for y in range(51):\n                quality = getNetworkQuality(x, y)\n                if quality > maxQuality:\n                    maxQuality = quality\n                    result = [x, y]\n        return result","hash":"23aa8bda8ce07ade847e43c80b7e71b45a26833faceb6c94c9d5ebdeea97ba1b","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 37/Coordinate With Maximum Network Quality.py"}]}],"sources":["solutions"]},"topic-corporateflightbookings":{"key":"topic-corporateflightbookings","number":null,"title":"Corporate Flight Bookings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Corporate Flight Bookings.py","code":"class Solution:\n    def corpFlightBookings(self, bookings: List[List[int]], n: int) -> List[int]:\n        dp = [0] * n\n        for i, j, k in bookings:\n            dp[i - 1] += k\n            if j < n:\n                dp[j] -= k\n        result = [0] * n\n        result[0] = dp[0]\n        for i in range(1, n):\n            result[i] = result[i - 1] + dp[i]\n        return result","hash":"166d9a2230560add4ee516ec795b82a0072c50bd8d8138b8f015ba3094520385","origins":[{"source":"solutions","path":"Corporate Flight Bookings.py"}]}],"sources":["solutions"]},"topic-countallvalidpickupanddeliveryoptions":{"key":"topic-countallvalidpickupanddeliveryoptions","number":null,"title":"Count All Valid Pickup and Delivery Options","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count All Valid Pickup and Delivery Options.py","code":"class Solution:\n    def countOrders(self, n: int) -> int:\n        @functools.cache\n        def totalWays(unpicked, undelivered):\n            if not unpicked and not undelivered:\n                #We have completed all orders\n                return 1\n            if (unpicked < 0 or undelivered < 0 or undelivered < unpicked):\n                # We can't pick or deliver more than N items\n                # Number of deliveries can't exceed number of pickups \n                # as we can only deliver after a pickup.\n                return 0\n            # Count all choices of picking up an order.\n            ans = unpicked * totalWays(unpicked - 1, undelivered)\n            ans %= MOD\n            # Count all choices of delivering a picked order.\n            ans += (undelivered - unpicked) * totalWays(unpicked, undelivered - 1)\n            ans %= MOD\n            return ans\n        MOD = 1_000_000_007\n        return totalWays(n, n)","hash":"ba4ad59964dc4010e9b00970fe36474eaf5eefd2e413ed04f5c2f38f20d603c0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Count All Valid Pickup and Delivery Options.py"}]}],"sources":["solutions"]},"topic-countbinarysubstrings":{"key":"topic-countbinarysubstrings","number":null,"title":"Count Binary Substrings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Binary Substrings.py","code":"class Solution:\n    def countBinarySubstrings(self, s: str) -> int:\n        currentCount, prevCount, result = 1, 0, 0\n        for i in range(1, len(s)):\n            if s[i] == s[i - 1]:\n                currentCount += 1\n            else:\n                result += min(currentCount, prevCount)\n                prevCount = currentCount\n                currentCount = 1\n        return result + min(currentCount, prevCount)","hash":"9dc0ef42f3007032df7ea27951bd769e53c0d8354116ae40e46eff3ab5cc772c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-04 Leetcoding Challenge/Count Binary Substrings.py"}]}],"sources":["solutions"]},"topic-countcommonwordswithoneoccurrence":{"key":"topic-countcommonwordswithoneoccurrence","number":null,"title":"Count Common Words With One Occurrence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Common Words With One Occurrence.py","code":"class Solution(object):\n    def countWords(self, words1, words2):\n        \"\"\"\n        :type words1: List[str]\n        :type words2: List[str]\n        :rtype: int\n        \"\"\"\n        hashMapA, hashMapB = defaultdict(int), defaultdict(int)\n        for word in words1:\n            hashMapA[word] += 1\n        for word in words2:\n            if word in hashMapA and hashMapA[word] == 1:\n                hashMapB[word] += 1\n        result = 0\n        for word in hashMapB:\n            if hashMapB[word] == 1:\n                result += 1\n        return result","hash":"e1c31505d9e5c95d647b263ff1f782d3028def7a953d1ccd3b67bbee59401fe7","origins":[{"source":"solutions","path":"Count Common Words With One Occurrence.py"}]}],"sources":["solutions"]},"topic-countelementswithstrictlysmallerandgreaterelements":{"key":"topic-countelementswithstrictlysmallerandgreaterelements","number":null,"title":"Count Elements With Strictly Smaller and Greater Elements","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Elements With Strictly Smaller and Greater Elements.py","code":"class Solution:\n    def countElements(self, nums: List[int]) -> int:\n        return max(0, len(nums) - nums.count(min(nums)) - nums.count(max(nums)))","hash":"d616ca4bc2070e8a2ac248051069ebe048f7130e7374d89a85defbdda1047ce2","origins":[{"source":"solutions","path":"Count Elements With Strictly Smaller and Greater Elements.py"}]}],"sources":["solutions"]},"topic-countgoodtriplets":{"key":"topic-countgoodtriplets","number":null,"title":"Count Good Triplets","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Good Triplets.py","code":"class Solution:\n    def countGoodTriplets(self, arr: List[int], a: int, b: int, c: int) -> int:\n        return sum(abs(x[0] - x[1]) <= a and abs(x[1] - x[2]) <= b and abs(x[0] - x[2]) <= c for x in combinations(arr, 3))","hash":"c8452d412018c648727454517c6cfc59f15b920003867ce11b946632a653b925","origins":[{"source":"solutions","path":"Count Good Triplets.py"}]}],"sources":["solutions"]},"topic-countintegersinintervals":{"key":"topic-countintegersinintervals","number":null,"title":"Count Integers in Intervals","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Integers in Intervals.py","code":"from sortedcontainers import SortedList\n\nclass CountIntervals:\n\n    def __init__(self):\n        self.currentCount = 0\n        self.intervals = SortedList()\n\n    def add(self, left: int, right: int) -> None:\n        k = self.intervals.bisect_left((left, right))\n        while k < len(self.intervals) and self.intervals[k][0] <= right:\n            l, r = self.intervals.pop(k)\n            self.currentCount -= r - l + 1\n            right = max(right, r)\n        if k and self.intervals[k - 1][1] >= left:\n            l, r = self.intervals.pop(k - 1)\n            self.currentCount -= r - l + 1\n            left, right = l, max(right, r)\n        self.currentCount += right - left + 1\n        self.intervals.add((left, right))\n\n    def count(self) -> int:\n        return self.currentCount\n\n\n# Your CountIntervals object will be instantiated and called as such:\n# obj = CountIntervals()\n# obj.add(left,right)\n# param_2 = obj.count()","hash":"06a36b2d9d18885f1c2e6c2cb2c30867f270ff20c2504533c53e9aeedfc4b79c","origins":[{"source":"solutions","path":"Count Integers in Intervals.py"}]}],"sources":["solutions"]},"topic-countitemsmatchingarule":{"key":"topic-countitemsmatchingarule","number":null,"title":"Count Items Matching a Rule","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Items Matching a Rule.py","code":"class Solution:\n    def countMatches(self, items: List[List[str]], ruleKey: str, ruleValue: str) -> int:\n        index = 0 if ruleKey == 'type' else 1 if ruleKey == 'color' else 2\n        return sum([1 for item in items if item[index] == ruleValue])","hash":"2cfce78d790f324b6bd3bdeff8465cd98b7d79d78332b9454ec3352692dfae35","origins":[{"source":"solutions","path":"Count Items Matching a Rule.py"}]}],"sources":["solutions"]},"topic-countlargestgroup":{"key":"topic-countlargestgroup","number":null,"title":"Count Largest Group","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Largest Group.py","code":"class Solution:\n    def countLargestGroup(self, n: int) -> int:\n        hashMap, maxGroupSize = defaultdict(int), 0\n        def getDigitSum(x):\n            currentSum = 0\n            while x:\n                currentSum += (x % 10)\n                x //= 10\n            return currentSum\n        for i in range(1, n + 1):\n            hashMap[getDigitSum(i)] += 1\n            maxGroupSize = max(maxGroupSize, hashMap[getDigitSum(i)])\n        return sum(1 for _, val in hashMap.items() if val == maxGroupSize)","hash":"ae7c98b41ed207d4d9a31957e34e21d8e67c8d20362e4d1e791383ddf5a525a2","origins":[{"source":"solutions","path":"Count Largest Group.py"}]}],"sources":["solutions"]},"topic-countnumberswithuniquedigits":{"key":"topic-countnumberswithuniquedigits","number":null,"title":"Count Numbers with Unique Digits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Numbers with Unique Digits.py","code":"class Solution:\n    def countNumbersWithUniqueDigits(self, n: int) -> int:\n        choices = [9, 9, 8, 7, 6, 5, 4, 3, 2, 1]\n        currentSum, currentFactor = 1, 1\n        for i in range(n):\n            currentFactor *= choices[i]\n            currentSum += currentFactor\n        return currentSum","hash":"b8ffe5245ee255362ca58b95b458407a8bd1a3e0bfe8ce4bcdde83b39c1ae849","origins":[{"source":"solutions","path":"Count Numbers with Unique Digits.py"}]}],"sources":["solutions"]},"topic-countoddnumbersinanintervalrange":{"key":"topic-countoddnumbersinanintervalrange","number":null,"title":"Count Odd Numbers in an Interval Range","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Odd Numbers in an Interval Range.py","code":"class Solution:\n    def countOdds(self, low: int, high: int) -> int:\n        diff = high - low\n        oddCount = diff >> 1\n        return oddCount if (high & 1 == 0 and low & 1 == 0) else oddCount + 1","hash":"e3292a6afb9e0cf1154a510afb2c2cf4ee5ef9c1a5f08150c0adbb8f4fe5cc06","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-02 Leetcoding Challenge/Count Odd Numbers in an Interval Range.py"}]}],"sources":["solutions"]},"topic-countofmatchesintournament":{"key":"topic-countofmatchesintournament","number":null,"title":"Count of Matches in Tournament","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count of Matches in Tournament.py","code":"class Solution:\n    def numberOfMatches(self, n: int) -> int:\n        teams, totalMatches = n, 0\n        while teams > 1:\n            if teams % 2 == 0:\n                memo = teams // 2\n                totalMatches += memo\n                teams = memo\n            else:\n                memo = (teams - 1) // 2\n                totalMatches += memo\n                teams = memo + 1\n        return totalMatches","hash":"0f595dfc8f3d4d640d32a5ff7d2d0af3dde8693cfe8149f7d7ad6c8efdb992f5","origins":[{"source":"solutions","path":"Count of Matches in Tournament.py"}]}],"sources":["solutions"]},"topic-countprefixesofagivenstring":{"key":"topic-countprefixesofagivenstring","number":null,"title":"Count Prefixes of a Given String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Prefixes of a Given String.py","code":"class Solution:\n    def countPrefixes(self, words: List[str], s: str) -> int:\n        hashSet = set(s[:i] for i in range(1, len(s) + 1))\n        result = 0\n        for word in words:\n            result += 1 if word in hashSet else 0\n        return result","hash":"0f92422f76a32fab8874ca3e850e0ec2293e7c0a4bba0f75d3b428fc75355fa3","origins":[{"source":"solutions","path":"Count Prefixes of a Given String.py"}]}],"sources":["solutions"]},"topic-countprimes":{"key":"topic-countprimes","number":null,"title":"Count Primes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Primes.py","code":"class Solution:\n    def countPrimes(self, n: int) -> int:\n        if n < 2:\n            return 0\n        isPrime = [True] * n\n        isPrime[0], isPrime[1] = False, False\n        for i in range(2, math.ceil(math.sqrt(n))):\n            if not isPrime[i]:\n                continue\n            for j in range(i * i, n, i):\n                isPrime[j] = False\n        return sum(isPrime)","hash":"483627fcce8bbb9a1d1505e3c3f80a787f6acf58c81804a9c84274b3976c5606","origins":[{"source":"solutions","path":"Count Primes.py"},{"source":"solutions","path":"LeetCoding Challenges/2021/2021-05 Leetcoding Challenge/Count Primes.py"},{"source":"solutions","path":"Top Interview Questions - Easy/Count Primes.py"}]}],"sources":["solutions"]},"topic-countsortedvowelstrings":{"key":"topic-countsortedvowelstrings","number":null,"title":"Count Sorted Vowel Strings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Sorted Vowel Strings.py","code":"class Solution:\n    def countVowelStrings(self, n: int) -> int:\n        return (n + 4) * (n + 3) * (n + 2) * (n + 1) // 24\n        # dp = [[0] * 6 for i in range(n + 1)]\n        # for vowel in range(1, 6):\n        #     dp[1][vowel] = vowel\n        # for nValue in range(2, n + 1):\n        #     dp[nValue][1] = 1\n        #     for vowel in range(2, 6):\n        #         dp[nValue][vowel] = dp[nValue - 1][vowel] + dp[nValue][vowel - 1]\n        # return dp[n][5]","hash":"c994a3bd4f74f96f01d2b2e396f57d266c48e2c56eec6d85ddac2af90b6bca0a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-01 Leetcoding Challenge/Count Sorted Vowel Strings.py"}]},{"language":"python","name":"Count Sorted Vowel Strings.py","code":"class Solution:\n    def countVowelStrings(self, n: int) -> int:\n        return (n + 4) * (n + 3) * (n + 2) * (n + 1) // 24","hash":"f3505fd5747d7ebb3b6afc489045d47415cac0875a1e1cbc6abe9c0b14f023e3","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Count Sorted Vowel Strings.py"}]}],"sources":["solutions"]},"topic-countsquaresumtriples":{"key":"topic-countsquaresumtriples","number":null,"title":"Count Square Sum Triples","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Square Sum Triples.py","code":"class Solution:\n    def countTriples(self, n: int) -> int:\n        result = 0\n        for i in range(1, n + 1):\n            for j in range (1, n + 1):\n                rootSumOfSquare = sqrt(i * i + j * j)\n                if rootSumOfSquare == math.floor(rootSumOfSquare) and rootSumOfSquare <= n:\n                    result += 1\n        return result","hash":"7175cd8e908baa2554c22f54b1547e409a4d7786e31be5afc54cbc2b0d5e1ec1","origins":[{"source":"solutions","path":"Count Square Sum Triples.py"}]}],"sources":["solutions"]},"topic-countsubstringsthatdifferbyonecharacter":{"key":"topic-countsubstringsthatdifferbyonecharacter","number":null,"title":"Count Substrings That Differ by One Character","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Substrings That Differ by One Character.py","code":"class Solution:\n    def countSubstrings(self, s: str, t: str) -> int:\n        sLength, tLength, result = len(s), len(t), 0\n        sameDP = [[0 for _ in range(tLength + 1)] for _ in range(sLength + 1)]\n        diffDP = [[0 for _ in range(tLength + 1)] for _ in range(sLength + 1)]\n        for i in range(sLength):\n            for j in range(tLength):\n                sameDP[i + 1][j + 1] = (sameDP[i][j] + 1) if s[i] == t[j] else 0\n        for i in range(sLength):\n            for j in range(tLength):\n                diffDP[i + 1][j + 1] = diffDP[i][j] if s[i] == t[j] else sameDP[i][j] + 1\n        for i in range(sLength + 1):\n            result += sum(diffDP[i])\n        return result","hash":"a9e129b48ecac19341e5f0d006e21f47c1703eec2946a82c6abf586d9c27033c","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 38/Count Substrings That Differ by One Character.py"}]}],"sources":["solutions"]},"topic-countsubtreeswithmaxdistancebetweencities":{"key":"topic-countsubtreeswithmaxdistancebetweencities","number":null,"title":"Count Subtrees With Max Distance Between Cities","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Subtrees With Max Distance Between Cities.py","code":"class Solution:\n    def countSubgraphsForEachDiameter(self, n: int, edges: List[List[int]]) -> List[int]:\n        graph = [[float('inf') for _ in range(n)] for _ in range(n)]\n        for u, v in edges:\n            graph[u - 1][v - 1] = graph[v - 1][u - 1] = 1\n        for k, i, j in permutations(range(n), 3):\n            graph[i][j] = min(graph[i][j], graph[i][k] + graph[k][j])\n        result = [0 for _ in range(n - 1)]\n        for numberOfVertices in range(2, n + 1):\n            for subset in combinations(range(n), numberOfVertices):\n                directEdgesInvolved = sum(graph[i][j] for i, j in combinations(subset, 2) if graph[i][j] == 1)\n                maxDistance = max(graph[i][j] for i, j in combinations(subset, 2))\n                if directEdgesInvolved == numberOfVertices - 1:\n                    result[maxDistance - 1] += 1\n        return result","hash":"de28f7ba4a27326e6e775511f0eb40732ddc80b9bb2861b6ef26a604aecd0a08","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 210/Count Subtrees With Max Distance Between Cities.py"}]}],"sources":["solutions"]},"topic-countthenumberofconsistentstrings":{"key":"topic-countthenumberofconsistentstrings","number":null,"title":"Count the Number of Consistent Strings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count the Number of Consistent Strings.py","code":"class Solution:\n    def countConsistentStrings(self, allowed: str, words: List[str]) -> int:\n        allowedSet = set(allowed)\n        def isConsistent(word: str):\n            wordSet = set(word)\n            for char in wordSet:\n                if char not in allowedSet:\n                    return False\n            return True\n        result = 0\n        for word in words:\n            if isConsistent(word):\n                result += 1\n        return result","hash":"af9b8e7f1032d5a648bde4e5c231b7af102789b28e69a28500bd9f4c364fb733","origins":[{"source":"solutions","path":"Count the Number of Consistent Strings.py"}]}],"sources":["solutions"]},"topic-countunhappyfriends":{"key":"topic-countunhappyfriends","number":null,"title":"Count Unhappy Friends","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Unhappy Friends.py","code":"class Solution:\n    def unhappyFriends(self, n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:\n        ranks, partners, unhappy = {}, defaultdict(int), 0\n        for p1, pref in enumerate(preferences):\n            ranks[p1] = defaultdict(lambda : n)\n            for rank, p2 in enumerate(pref):\n                ranks[p1][p2] = rank\n        for p1, p2 in pairs:\n            partners[p1] = p2\n            partners[p2] = p1\n        for p1, p2 in pairs:\n            for peer in preferences[p1]:\n                if ranks[p1][peer] < ranks[p1][p2] and ranks[peer][p1] < ranks[peer][partners[peer]]:\n                    unhappy += 1\n                    break\n            for peer in preferences[p2]:\n                if ranks[p2][peer] < ranks[p2][p1] and ranks[peer][p2] < ranks[peer][partners[peer]]:\n                    unhappy += 1\n                    break\n        return unhappy","hash":"efc6f4c6e599dc22226ebe40b0e5b95ee8943cdf68acacd5477f233dd0b17a71","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 206/Count Unhappy Friends.py"}]}],"sources":["solutions"]},"topic-countunreachablepairsofnodesinanundirectedgraph":{"key":"topic-countunreachablepairsofnodesinanundirectedgraph","number":null,"title":"Count Unreachable Pairs of Nodes in an Undirected Graph","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Count Unreachable Pairs of Nodes in an Undirected Graph.py","code":"class Solution:\n    def countPairs(self, n: int, edges: List[List[int]]) -> int:\n        graph = defaultdict(set)\n        visited, numberOfPairs, remainingNodes, sizeOfComponent = set(), 0, n, 0\n        for edgeStart, edgeEnd in edges:\n            graph[edgeStart].add(edgeEnd)\n            graph[edgeEnd].add(edgeStart)\n        def dfs(node):\n            count = 1\n            visited.add(node)\n            if node not in graph:\n                return count\n            for neighbour in graph[node]:\n                if neighbour not in visited:\n                    count += dfs(neighbour)\n            return count\n        for i in range(n):\n            if i not in visited:\n                sizeOfComponent = dfs(i)\n                numberOfPairs += sizeOfComponent * (remainingNodes - sizeOfComponent)\n                remainingNodes -= sizeOfComponent\n        return numberOfPairs","hash":"7770f3947372724b117edb5455dabf4bcc8cfaa49c180404735a5103c7d7c41b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-03 Leetcoding Challenge/Count Unreachable Pairs of Nodes in an Undirected Graph.py"}]}],"sources":["solutions"]},"topic-countingbits":{"key":"topic-countingbits","number":null,"title":"Counting Bits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Counting Bits.py","code":"class Solution:\n    def countBits(self, num: int) -> List[int]:\n        result, i, b = [0] * (num + 1), 0, 1\n        while b <= num:\n            while i < b and i + b <= num:\n                result[i + b] = result[i] + 1\n                i += 1\n            i, b = 0, b << 1\n        return result","hash":"9002edba333f304619b1bb57894642caf018176b81a34ffd1cb871a61d5d282b","origins":[{"source":"solutions","path":"Counting Bits.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Counting Bits.py"}]}],"sources":["solutions"]},"topic-countingwordswithagivenprefix":{"key":"topic-countingwordswithagivenprefix","number":null,"title":"Counting Words With a Given Prefix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Counting Words With a Given Prefix.py","code":"class Solution:\n    def prefixCount(self, words: List[str], pref: str) -> int:\n        result = 0\n        for word in words:\n            result += 1 if word.startswith(pref) else 0\n        return result","hash":"821ffaa0da0d03800cf961723d1c707ad83ed50831b073098cb9eed9bd13ca74","origins":[{"source":"solutions","path":"Counting Words With a Given Prefix.py"}]}],"sources":["solutions"]},"topic-coursescheduleiidfs":{"key":"topic-coursescheduleiidfs","number":null,"title":"Course Schedule II DFS","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Course Schedule II - DFS.py","code":"class Solution:\n    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:\n        WHITE = 1\n        GRAY = 2\n        BLACK = 3\n        adjacencyList = defaultdict(list)\n        for destination, source in prerequisites:\n            adjacencyList[source].append(destination)\n        color = {node: WHITE for node in range(numCourses)}\n        topologicalSortedOrder = []\n        isValid = True\n        def dfs(node):\n            nonlocal isValid, topologicalSortedOrder, color, adjacencyList\n            if not isValid:\n                return\n            color[node] = GRAY\n            if node in adjacencyList:\n                for destination in adjacencyList[node]:\n                    if color[destination] == WHITE:\n                        dfs(destination)\n                    elif color[destination] == GRAY:\n                        isValid = False\n            color[node] = BLACK\n            topologicalSortedOrder.append(node)\n        for node in range(numCourses):\n            if color[node] == WHITE:\n                dfs(node)\n        return topologicalSortedOrder[::-1] if isValid else []","hash":"fbfa61c2b22598b8ec8a6b5fa2a1f1f65a7a378b680b7589481f5c3510947797","origins":[{"source":"solutions","path":"Google Interview Questions/Course Schedule II - DFS.py"}]}],"sources":["solutions"]},"topic-coursescheduleiinodeindegree":{"key":"topic-coursescheduleiinodeindegree","number":null,"title":"Course Schedule II Node in degree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Course Schedule II - Node in-degree.py","code":"class Solution:\n    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:\n        adjacencyList = defaultdict(list)\n        nodeInDegree = {}\n        for destination, source in prerequisites:\n            adjacencyList[source].append(destination)\n            nodeInDegree[destination] = nodeInDegree.get(destination, 0) + 1\n        zeroInDegreeQueue = deque([node for node in range(numCourses) if node not in nodeInDegree])\n        topologicalSort = []\n        while zeroInDegreeQueue:\n            node = zeroInDegreeQueue.popleft()\n            topologicalSort.append(node)\n            if node in adjacencyList:\n                for neighbour in adjacencyList[node]:\n                    nodeInDegree[neighbour] -= 1\n                    if nodeInDegree[neighbour] == 0:\n                        zeroInDegreeQueue.append(neighbour)\n        return topologicalSort if len(topologicalSort) == numCourses else []","hash":"539e1fad825c0c33fe19394f40474a42aacd6b7e2c99311db1fe163922b3b0f3","origins":[{"source":"solutions","path":"Google Interview Questions/Course Schedule II - Node in-degree.py"}]}],"sources":["solutions"]},"topic-cousinsinbinarytree":{"key":"topic-cousinsinbinarytree","number":null,"title":"Cousins in Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Cousins in Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isCousins(self, root: TreeNode, x: int, y: int) -> bool:\n        queue = deque([root])\n        while queue:\n            siblings, cousins = False, False\n            nodesAtThisDepth = len(queue)\n            for _ in range(nodesAtThisDepth):\n                node = queue.popleft()\n                if node is None:\n                    siblings = False\n                else:\n                    if node.val == x or node.val == y:\n                        if not cousins:\n                            cousins, siblings = True, True\n                        else:\n                            return not siblings\n                    queue.append(node.left) if node.left else None\n                    queue.append(node.right) if node.right else None\n                    queue.append(None)\n            if cousins:\n                return False\n        return False","hash":"1f83cdc3597621526b96f3f9e7ac4614a19aa2371aa74a6bcc286b3bfdae4f9f","origins":[{"source":"solutions","path":"Cousins in Binary Tree.py"}]}],"sources":["solutions"]},"topic-covertbsttogreatertree":{"key":"topic-covertbsttogreatertree","number":null,"title":"Covert BST to Greater Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Covert BST to Greater Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def convertBST(self, root: TreeNode) -> TreeNode:\n        currentSum = 0\n        def dfs(node):\n            nonlocal currentSum\n            if node:\n                dfs(node.right)\n                currentSum += node.val\n                node.val = currentSum\n                dfs(node.left)\n        dfs(root)\n        return root","hash":"7061aca66c678d90017bc2ff6b5c03280ac3293643535eec5dea771ec1e68f97","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Covert BST to Greater Tree.py"}]}],"sources":["solutions"]},"topic-crawlerlogfolder":{"key":"topic-crawlerlogfolder","number":null,"title":"Crawler Log Folder","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Crawler Log Folder.py","code":"class Solution:\n    def minOperations(self, logs: List[str]) -> int:\n        depth = 0\n        for log in logs:\n            if log == '../':\n                depth = depth - 1 if depth > 0 else 0\n            elif log == './':\n                continue\n            else:\n                depth += 1\n        return depth","hash":"2fedc6b92bb4cdf21c31f488571dcb6a1be693610c2462e7110a169db2a0c433","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 208/Crawler Log Folder.py"}]}],"sources":["solutions"]},"topic-createsortedarraythroughinstructions":{"key":"topic-createsortedarraythroughinstructions","number":null,"title":"Create Sorted Array through Instructions","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Create Sorted Array through Instructions.py","code":"from sortedcontainers import SortedList\n\nclass Solution:\n    def createSortedArray(self, instructions: List[int]) -> int:\n        sortedList, MOD, cost, size = SortedList(), 10**9 + 7, 0, len(instructions)\n        for i in range(size):\n            leftCost, rightCost = sortedList.bisect_left(instructions[i]), i - sortedList.bisect_right(instructions[i])\n            cost += min(leftCost, rightCost)\n            sortedList.add(instructions[i])\n        return cost % MOD","hash":"86d421f4b582738632e41a83c0078823c5edccffef53a478bd1443f08f6e3127","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-01 Leetcoding Challenge/Create Sorted Array through Instructions.py"}]}],"sources":["solutions"]},"topic-createtargetarrayinthegivenorder":{"key":"topic-createtargetarrayinthegivenorder","number":null,"title":"Create Target Array in the Given Order","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Create Target Array in the Given Order.py","code":"class Solution:\n    def createTargetArray(self, nums: List[int], index: List[int]) -> List[int]:\n        target = []\n        for i in range(len(nums)):\n            target.insert(index[i], nums[i])\n        return target","hash":"133473f0c7655d3114b8b34646d3f3868dc3bd1c0a841903d3e64c5410317c17","origins":[{"source":"solutions","path":"Create Target Array in the Given Order.py"}]}],"sources":["solutions"]},"topic-criticalconnectionsinanetwork":{"key":"topic-criticalconnectionsinanetwork","number":null,"title":"Critical Connections in a Network","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Critical Connections in a Network.py","code":"class Solution:\n    def criticalConnections(self, n: int, connections: List[List[int]]) -> List[List[int]]:\n        graph = defaultdict(set)\n        for a, b in connections:\n            graph[a].add(b)\n            graph[b].add(a)\n        discoveryTime = [-1 for _ in range(n)]\n        lowTime = [-1 for _ in range(n)]\n        seen = [False for _ in range(n)]\n        time, result = 0, []\n        \n        def dfs(node, parent = None):\n            nonlocal time\n            discoveryTime[node] = time\n            lowTime[node] = time\n            seen[node] = True\n            time += 1\n            for neighbour in graph[node]:\n                if neighbour == parent:\n                    continue\n                if seen[neighbour]:\n                    lowTime[node] = min(lowTime[node], discoveryTime[neighbour])\n                else:\n                    dfs(neighbour, node)\n                    lowTime[node] = min(lowTime[node], lowTime[neighbour])\n                    if lowTime[neighbour] > discoveryTime[node]:\n                        result.append([node, neighbour])\n        \n        for i in range(n):\n            if not seen[i]:\n                dfs(i)\n        return result","hash":"db09dc90867af4d95a388a30c270789f94d12caba68963368efcb08c85fb32a1","origins":[{"source":"solutions","path":"Critical Connections in a Network.py"},{"source":"solutions","path":"LeetCoding Challenges/2021/2021-04 Leetcoding Challenge/Critical Connections in a Network.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Critical Connections in a Network.py"}]}],"sources":["solutions"]},"topic-customsortstring":{"key":"topic-customsortstring","number":null,"title":"Custom Sort String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Custom Sort String.py","code":"class Solution:\n    def customSortString(self, order: str, str: str) -> str:\n        count, result = collections.Counter(str), []\n        for char in order:\n            result.append(char * count[char])\n            count[char] = 0\n        for char in count:\n            result.append(char * count[char])\n        return ''.join(result)","hash":"8aca6f319c6301d6603304ad01b8ba75cd601c9bb5d83ba9bdc6043c018019c7","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/Custom Sort String.py"}]}],"sources":["solutions"]},"topic-customerplacingthelargestnumberoforders":{"key":"topic-customerplacingthelargestnumberoforders","number":null,"title":"Customer Placing the Largest Number of Orders","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"sql","name":"Customer Placing the Largest Number of Orders.sql","code":"# Write your MySQL query statement below\nSELECT customer_number \nFROM Orders \nGROUP BY customer_number \nORDER BY Count(*) DESC\nLIMIT 1","hash":"3c5812eb944a68ffd227da90e49cdd5d3ea11269e85adf82b10e510f81574615","origins":[{"source":"solutions","path":"Customer Placing the Largest Number of Orders.sql"}]}],"sources":["solutions"]},"topic-dailytemperatures":{"key":"topic-dailytemperatures","number":null,"title":"Daily Temperatures","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Daily Temperatures.py","code":"class Solution:\n    def dailyTemperatures(self, T: List[int]) -> List[int]:\n        inputArrayLength = len(T)\n        result = [0] * inputArrayLength\n        stack = deque()\n        for i in range(inputArrayLength - 1, -1, -1):\n            while stack and T[i] >= T[stack[-1]]:\n                stack.pop()\n            if stack:\n                result[i] = stack[-1] - i\n            stack.append(i)\n        return result","hash":"d3790e1985e4adaf6dc25c89d5ee8678d490c7de5e6f2e4f3de3be07e8ec5b02","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Daily Temperatures.py"},{"source":"solutions","path":"Stacks and Queues/Daily Temperatures.py"}]}],"sources":["solutions"]},"topic-datastreamasdisjointintervals":{"key":"topic-datastreamasdisjointintervals","number":null,"title":"Data Stream as Disjoint Intervals","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Data Stream as Disjoint Intervals.py","code":"from sortedcontainers import SortedSet\n\nclass SummaryRanges:\n\n    def __init__(self):\n        self._values = SortedSet()\n\n    def addNum(self, value: int) -> None:\n        self._values.add(value)\n\n    def getIntervals(self) -> List[List[int]]:\n        if len(self._values) == 0:\n            return []\n        intervals, left, right = [], -1, -1\n        for value in self._values:\n            if left < 0:\n                left = right = value\n            elif value == right + 1:\n                right = value\n            else:\n                intervals.append([left, right])\n                left = right = value\n        intervals.append([left, right])\n        return intervals\n\n\n# Your SummaryRanges object will be instantiated and called as such:\n# obj = SummaryRanges()\n# obj.addNum(value)\n# param_2 = obj.getIntervals()","hash":"0ca1d9b17a5ff65d0a4bca5f92c8ba3c3ea8f3610e4cd64cb1d680908e05c444","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Data Stream as Disjoint Intervals.py"}]}],"sources":["solutions"]},"topic-day0101binarysearch":{"key":"topic-day0101binarysearch","number":null,"title":"Day 01 01 Binary Search","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 01-01 Binary Search.py","code":"class Solution:\n    def search(self, nums: List[int], target: int) -> int:\n        low, high = 0, len(nums)\n        while low < high:\n            mid = low + (high - low) // 2\n            if nums[mid] == target:\n                return mid\n            elif nums[mid] < target:\n                low = mid + 1\n            else:\n                high = mid\n        return -1","hash":"a12623ba522dfe245b536461f0a3e655465a4b2b60def5108cf7fa2305a70224","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 01-01 Binary Search.py"}]}],"sources":["solutions"]},"topic-day0101containsduplicate":{"key":"topic-day0101containsduplicate","number":null,"title":"Day 01 01 Contains Duplicate","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 01-01 Contains Duplicate.py","code":"class Solution:\n    def containsDuplicate(self, nums: List[int]) -> bool:\n        hashSet = set()\n        for num in nums:\n            if num in hashSet:\n                return True\n            hashSet.add(num)\n        return False","hash":"060f17e98fe2ae3fc04460fbc0b66631325eb61964dc8a9cb4fd288c731c3372","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 01-01 Contains Duplicate.py"}]}],"sources":["solutions"]},"topic-day0102firstbadversion":{"key":"topic-day0102firstbadversion","number":null,"title":"Day 01 02 First Bad Version","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 01-02 First Bad Version.py","code":"# The isBadVersion API is already defined for you.\n# def isBadVersion(version: int) -> bool:\n\nclass Solution:\n    def firstBadVersion(self, n: int) -> int:\n        low, high = 1, n\n        while low < high:\n            mid = (high + low) >> 1\n            if isBadVersion(mid):\n                high = mid\n            else:\n                low = mid + 1\n        return low","hash":"1b335b4d6de8fdf1a2e6ce5bc962ce6697becf691eb7150933706ca61ef6a230","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 01-02 First Bad Version.py"}]}],"sources":["solutions"]},"topic-day0102maximumsubarray":{"key":"topic-day0102maximumsubarray","number":null,"title":"Day 01 02 Maximum Subarray","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 01-02 Maximum Subarray.py","code":"class Solution:\n    def maxSubArray(self, nums: List[int]) -> int:\n        result = nums[0]\n        for i in range(1, len(nums)):\n            if nums[i - 1] > 0:\n                nums[i] += nums[i - 1]\n            result = max(result, nums[i])\n        return result","hash":"152ee91e9544c6896477c7ccc1560139e043b379121c774b6f13231b51d1a3b3","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 01-02 Maximum Subarray.py"}]}],"sources":["solutions"]},"topic-day0103searchinsertposition":{"key":"topic-day0103searchinsertposition","number":null,"title":"Day 01 03 Search Insert Position","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 01-03 Search Insert Position.py","code":"class Solution:\n    def searchInsert(self, nums: List[int], target: int) -> int:\n        low, high = 0, len(nums)\n        while low < high:\n            mid = (low + high) >> 1\n            if nums[mid] == target:\n                return mid\n            elif nums[mid] < target:\n                low = mid + 1\n            else:\n                high = mid\n        return low","hash":"9d4b622e19f333944aad0108d87d27cc4ff4274cdd68907899c85416bbcafa02","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 01-03 Search Insert Position.py"}]}],"sources":["solutions"]},"topic-day0201squaresofasortedarray":{"key":"topic-day0201squaresofasortedarray","number":null,"title":"Day 02 01 Squares of a Sorted Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 02-01 Squares of a Sorted Array.py","code":"class Solution:\n    def sortedSquares(self, nums: List[int]) -> List[int]:\n        return sorted(num * num for num in nums)","hash":"647d68b729bcac9f21a1c1341c1deba959a6c6e1b722a1664d8e6abf1a4a8b31","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 02-01 Squares of a Sorted Array.py"}]}],"sources":["solutions"]},"topic-day0201twosum":{"key":"topic-day0201twosum","number":null,"title":"Day 02 01 Two Sum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 02-01 Two Sum.py","code":"class Solution:\n    def twoSum(self, nums: List[int], target: int) -> List[int]:\n        hashMap = {}\n        for i, num in enumerate(nums):\n            complementNumber = target - num\n            if complementNumber in hashMap:\n                return [hashMap[complementNumber], i]\n            hashMap[num] = i\n        return []","hash":"d9d53126d9d9f3e23abb47e19b1ac55483ce68167ce88e81d2cb8d017fed55af","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 02-01 Two Sum.py"}]}],"sources":["solutions"]},"topic-day0202mergesortedarray":{"key":"topic-day0202mergesortedarray","number":null,"title":"Day 02 02 Merge Sorted Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 02-02 Merge Sorted Array.py","code":"class Solution:\n    def merge(self, nums1: List[int], m: int, nums2: List[int], n: int) -> None:\n        \"\"\"\n        Do not return anything, modify nums1 in-place instead.\n        \"\"\"\n        i, j, k = m - 1, n - 1, m + n - 1\n        while i >= 0 and j >= 0:\n            if nums1[i] >= nums2[j]:\n                nums1[k] = nums1[i]\n                i -= 1\n            else:\n                nums1[k] = nums2[j]\n                j -= 1\n            k -= 1\n        if j >= 0:\n            while k >= 0:\n                nums1[k] = nums2[j]\n                j -= 1\n                k -= 1","hash":"d58b1aaed8261763e2e3dfa8d0c169083a71632a6eb0ac71ef1ad1a32dbd0cce","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 02-02 Merge Sorted Array.py"}]}],"sources":["solutions"]},"topic-day0202rotatearray":{"key":"topic-day0202rotatearray","number":null,"title":"Day 02 02 Rotate Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 02-02 Rotate Array.py","code":"class Solution:\n    def rotate(self, nums: List[int], k: int) -> None:\n        \"\"\"\n        Do not return anything, modify nums in-place instead.\n        \"\"\"\n        def reverse(start, end):\n            while start < end:\n                nums[start], nums[end] = nums[end], nums[start]\n                start, end = start + 1, end - 1\n        \n        n = len(nums)\n        k %= n\n        reverse(0, n - 1)\n        reverse(0, k - 1)\n        reverse(k, n - 1)","hash":"59395716e309a9e20fb09766f768cc6f9d51beb82dcf28476e18a7cfa8ffb288","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 02-02 Rotate Array.py"}]}],"sources":["solutions"]},"topic-day0301intersectionoftwoarraysii":{"key":"topic-day0301intersectionoftwoarraysii","number":null,"title":"Day 03 01 Intersection of Two Arrays II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 03-01 Intersection of Two Arrays II.py","code":"class Solution:\n    def intersect(self, nums1: List[int], nums2: List[int]) -> List[int]:\n        if len(nums1) > len(nums2):\n            nums1, nums2 = nums2, nums1\n        nums1FreqMap = Counter(nums1) # nums1 has smaller length\n        result = []\n        for num in nums2:\n            if num in nums1FreqMap and nums1FreqMap[num] > 0:\n                nums1FreqMap[num] -= 1\n                result.append(num)\n        return result","hash":"6a2f4a5065df6ddfbe4528818e3aa17e29a3ce7ac27abc28d3fcd593003e05fe","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 03-01 Intersection of Two Arrays II.py"}]}],"sources":["solutions"]},"topic-day0301movezeroes":{"key":"topic-day0301movezeroes","number":null,"title":"Day 03 01 Move Zeroes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 03-01 Move Zeroes.py","code":"class Solution:\n    def moveZeroes(self, nums: List[int]) -> None:\n        \"\"\"\n        Do not return anything, modify nums in-place instead.\n        \"\"\"\n        i, j, N = 0, 0, len(nums)\n        while j < N:\n            if nums[j] != 0:\n                nums[i] = nums[j]\n                i += 1\n            j += 1\n        while i < N:\n            nums[i] = 0\n            i += 1","hash":"4c760b4ca52772c6e8e108bec246b10cdf863b7c712f0eb51bb919d591b1641c","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 03-01 Move Zeroes.py"}]}],"sources":["solutions"]},"topic-day0302besttimetobuyandsellstock":{"key":"topic-day0302besttimetobuyandsellstock","number":null,"title":"Day 03 02 Best Time to Buy and Sell Stock","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 03-02 Best Time to Buy and Sell Stock.py","code":"class Solution:\n    def maxProfit(self, prices: List[int]) -> int:\n        buy, result = 100000, 0\n        for price in prices:\n            if price >= buy:\n                result = max(result, price - buy)\n            buy = min(price, buy)\n        return result","hash":"1a14faeba340c055665e549189a5b374c0865eb2d920100203a744fae4634c64","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 03-02 Best Time to Buy and Sell Stock.py"}]}],"sources":["solutions"]},"topic-day0302twosumiiinputarrayissorted":{"key":"topic-day0302twosumiiinputarrayissorted","number":null,"title":"Day 03 02 Two Sum II Input Array Is Sorted","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 03-02 Two Sum II - Input Array Is Sorted.py","code":"class Solution:\n    def twoSum(self, numbers: List[int], target: int) -> List[int]:\n        low = 0\n        high = len(numbers) - 1\n        while low < high:\n            currentSum = numbers[low] + numbers[high]\n            if currentSum == target:\n                return [low + 1, high + 1]\n            elif currentSum < target:\n                low += 1\n            else:\n                high -= 1\n        return [-1, -1]","hash":"b81cd079a79b16e380589d09742573d121f16b814be5d3c732c209e30ebb63de","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 03-02 Two Sum II - Input Array Is Sorted.py"}]}],"sources":["solutions"]},"topic-day0401reshapethematrix":{"key":"topic-day0401reshapethematrix","number":null,"title":"Day 04 01 Reshape the Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 04-01 Reshape the Matrix.py","code":"class Solution:\n    def matrixReshape(self, mat: List[List[int]], r: int, c: int) -> List[List[int]]:\n        if len(mat) == 0 or (r * c != len(mat) * len(mat[0])):\n            return mat\n        result, count = [[0] * c for _ in range(r)], 0\n        for i in range(len(mat)):\n            for j in range(len(mat[0])):\n                result[count // c][count % c], count = mat[i][j], count + 1\n        return result","hash":"e219572ff034e99bb168c341e255ec2b956c224c7630915cc0c49107958ba85a","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 04-01 Reshape the Matrix.py"}]}],"sources":["solutions"]},"topic-day0401reversestring":{"key":"topic-day0401reversestring","number":null,"title":"Day 04 01 Reverse String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 04-01 Reverse String.py","code":"class Solution:\n    def reverseString(self, s: List[str]) -> None:\n        \"\"\"\n        Do not return anything, modify s in-place instead.\n        \"\"\"\n        def helper(left, right):\n            if left < right:\n                s[left], s[right] = s[right], s[left]\n                helper(left + 1, right - 1)\n        helper(0, len(s) - 1)","hash":"3da9a1b2152e93080acfa818070e4620bfb726c2b5c9a656e577e71c57567713","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 04-01 Reverse String.py"}]}],"sources":["solutions"]},"topic-day0402pascalstriangle":{"key":"topic-day0402pascalstriangle","number":null,"title":"Day 04 02 Pascal's Triangle","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 04-02 Pascal's Triangle.py","code":"class Solution:\n    def generate(self, numRows: int) -> List[List[int]]:\n        triangle = []\n        for rowNumber in range(numRows):\n            row = [None] * (rowNumber + 1)\n            row[0], row[-1] = 1, 1\n            for i in range(1, rowNumber):\n                row[i] = triangle[rowNumber - 1][i - 1] + triangle[rowNumber - 1][i]\n            triangle.append(row)\n        return triangle","hash":"600ac76789b97eb4239ca18686d18330365ebe0b6bd7ce0307ffe62d38231edb","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 04-02 Pascal's Triangle.py"}]}],"sources":["solutions"]},"topic-day0402reversewordsinastringiii":{"key":"topic-day0402reversewordsinastringiii","number":null,"title":"Day 04 02 Reverse Words in a String III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 04-02 Reverse Words in a String III.py","code":"class Solution:\n    def reverseWords(self, s: str) -> str:\n        wordList = s.split(' ')\n        for i in range(len(wordList)):\n            wordList[i] = wordList[i][::-1]\n        return ' '.join(wordList)","hash":"c217a6de02d26ddabbe47b24e3a139e08a2cc02162d5b5d1ee454433e1d46658","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 04-02 Reverse Words in a String III.py"}]}],"sources":["solutions"]},"topic-day0501middleofthelinkedlist":{"key":"topic-day0501middleofthelinkedlist","number":null,"title":"Day 05 01 Middle of the Linked List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 05-01 Middle of the Linked List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def middleNode(self, head: Optional[ListNode]) -> Optional[ListNode]:\n        slow, fast = head, head\n        while fast and fast.next:\n            slow = slow.next\n            fast = fast.next.next\n        return slow","hash":"8958245ec30d94780d00864ba8a3e016c7e6b1b066ca3664eff370ef86e24093","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 05-01 Middle of the Linked List.py"}]}],"sources":["solutions"]},"topic-day0501validsudoku":{"key":"topic-day0501validsudoku","number":null,"title":"Day 05 01 Valid Sudoku","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 05-01 Valid Sudoku.py","code":"class Solution:\n    def isValidSudoku(self, board: List[List[str]]) -> bool:\n        rows = [defaultdict(int) for _ in range(9)]\n        cols = [defaultdict(int) for _ in range(9)]\n        boxes = [defaultdict(int) for _ in range(9)]\n        for row in range(9):\n            for col in range(9):\n                boxIndex = ((row // 3) * 3) + (col // 3)\n                if board[row][col] != '.':\n                    number = int(board[row][col])\n                    rows[row][number] += 1\n                    cols[col][number] += 1\n                    boxes[boxIndex][number] += 1\n                    if rows[row][number] > 1 or cols[col][number] > 1 or boxes[boxIndex][number] > 1:\n                        return False\n        return True","hash":"1f638230b26da0ad7fc2921dfd1c1689bc4585a52e5411c9e47264b09b73cc39","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 05-01 Valid Sudoku.py"}]}],"sources":["solutions"]},"topic-day0502removenthnodefromendoflist":{"key":"topic-day0502removenthnodefromendoflist","number":null,"title":"Day 05 02 Remove Nth Node From End of List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 05-02 Remove Nth Node From End of List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def removeNthFromEnd(self, head: ListNode, n: int) -> ListNode:\n        dummyNode = ListNode(0)\n        dummyNode.next = head\n        currentNode = dummyNode\n        leadNode = dummyNode\n        while n > -1:\n            leadNode = leadNode.next\n            n -= 1\n        while leadNode:\n            currentNode = currentNode.next\n            leadNode = leadNode.next\n        currentNode.next = currentNode.next.next\n        return dummyNode.next","hash":"b6d04acf837a491ccb41b8b50fdf8ab202e6d36dbb73c2170e35b11a2161ebdd","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 05-02 Remove Nth Node From End of List.py"}]}],"sources":["solutions"]},"topic-day0502searcha2dmatrix":{"key":"topic-day0502searcha2dmatrix","number":null,"title":"Day 05 02 Search a 2D Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 05-02 Search a 2D Matrix.py","code":"class Solution:\n    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:\n        rows = len(matrix)\n        if rows == 0:\n            return False\n        cols = len(matrix[0])\n        size = rows * cols\n        low, high = 0, size - 1\n        while low <= high:\n            mid = low + ((high - low) // 2)\n            row, col = mid // cols, mid % cols\n            if matrix[row][col] == target:\n                return True\n            elif matrix[row][col] < target:\n                low = mid + 1\n            else:\n                high = mid - 1\n        return False","hash":"3cd372d62786230cf369235dd9d41f19e73c5870b3ec01538aba267485621e58","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 05-02 Search a 2D Matrix.py"}]}],"sources":["solutions"]},"topic-day0601firstuniquecharacterinastring":{"key":"topic-day0601firstuniquecharacterinastring","number":null,"title":"Day 06 01 First Unique Character in a String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 06-01 First Unique Character in a String.py","code":"class Solution:\n    def firstUniqChar(self, s: str) -> int:\n        charMap = Counter(s)\n        for i, c in enumerate(s):\n            if charMap[c] == 1:\n                return i\n        return -1","hash":"6d85cca16712ade4016d21af157d56755b1c678d13c1b6a38b147ced373cbaa3","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 06-01 First Unique Character in a String.py"}]}],"sources":["solutions"]},"topic-day0601longestsubstringwithoutrepeatingcharacters":{"key":"topic-day0601longestsubstringwithoutrepeatingcharacters","number":null,"title":"Day 06 01 Longest Substring Without Repeating Characters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 06-01 Longest Substring Without Repeating Characters.py","code":"class Solution:\n    def lengthOfLongestSubstring(self, s: str) -> int:\n        maxWindow = 0\n        start = end = 0\n        alphabets = set()\n        while( end < len(s) ):\n            if( s[end] not in alphabets ):\n                alphabets.add(s[end])\n                end += 1\n                maxWindow = max( maxWindow, end - start )\n            else:\n                alphabets.remove(s[start])\n                start += 1\n        return maxWindow","hash":"bf5c35acbd2fd47f8afb0aba37cf30ef8dde24512abca73fe5f4553b7eca3a1b","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 06-01 Longest Substring Without Repeating Characters.py"}]}],"sources":["solutions"]},"topic-day0602permutationinstring":{"key":"topic-day0602permutationinstring","number":null,"title":"Day 06 02 Permutation in String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 06-02 Permutation in String.py","code":"class Solution:\n    def checkInclusion(self, s1: str, s2: str) -> bool:\n        cntr, w, match = Counter(s1), len(s1), 0     \n\n        for i in range(len(s2)):\n            if s2[i] in cntr:\n                if not cntr[s2[i]]: match -= 1\n                cntr[s2[i]] -= 1\n                if not cntr[s2[i]]: match += 1\n\n            if i >= w and s2[i-w] in cntr:\n                if not cntr[s2[i-w]]: match -= 1\n                cntr[s2[i-w]] += 1\n                if not cntr[s2[i-w]]: match += 1\n\n            if match == len(cntr):\n                return True\n\n        return False","hash":"0c06c6f783f2164adf2b9231c0ac6b904c3380448bb3fc43c39cccd7ca299074","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 06-02 Permutation in String.py"}]}],"sources":["solutions"]},"topic-day0602ransomnote":{"key":"topic-day0602ransomnote","number":null,"title":"Day 06 02 Ransom Note","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 06-02 Ransom Note.py","code":"class Solution:\n    def canConstruct(self, ransomNote: str, magazine: str) -> bool:\n        ransomFreqMap, magazineFreqMap = Counter(ransomNote), Counter(magazine)\n        for char, freq in ransomFreqMap.items():\n            if char not in magazineFreqMap or freq > magazineFreqMap[char]:\n                return False\n        return True","hash":"5d489933dfab26033a41fcfcc3f81e104d5333d3a3268f8a4a4737e8f5d20b12","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 06-02 Ransom Note.py"}]}],"sources":["solutions"]},"topic-day0603validanagram":{"key":"topic-day0603validanagram","number":null,"title":"Day 06 03 Valid Anagram","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 06-03 Valid Anagram.py","code":"class Solution:\n    def isAnagram(self, s: str, t: str) -> bool:\n        return Counter(s) == Counter(t)","hash":"8a0506541390943759e349d16739226aa9108ac1bf3aa3ffff40fd9967d89af3","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 06-03 Valid Anagram.py"}]}],"sources":["solutions"]},"topic-day0701floodfill":{"key":"topic-day0701floodfill","number":null,"title":"Day 07 01 Flood Fill","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 07-01 Flood Fill.py","code":"class Solution:\n    def floodFill(self, image: List[List[int]], sr: int, sc: int, newColor: int) -> List[List[int]]:\n        rows, cols, color = len(image), len(image[0]), image[sr][sc]\n        if color == newColor:\n            return image\n        def dfs(row, col):\n            if image[row][col] == color:\n                image[row][col] = newColor\n                if row - 1 >= 0:\n                    dfs(row - 1, col)\n                if row + 1 < rows:\n                    dfs(row + 1, col)\n                if col - 1 >= 0:\n                    dfs(row, col - 1)\n                if col + 1 < cols:\n                    dfs(row, col + 1)\n        dfs(sr, sc)\n        return image","hash":"bed267c21c34eb38328b60fe9cceeed7f933a89f2b6418e03473cd061f830d3e","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 07-01 Flood Fill.py"}]}],"sources":["solutions"]},"topic-day0701linkedlistcycle":{"key":"topic-day0701linkedlistcycle","number":null,"title":"Day 07 01 Linked List Cycle","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 07-01 Linked List Cycle.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, x):\n#         self.val = x\n#         self.next = None\n\nclass Solution:\n    def hasCycle(self, head: Optional[ListNode]) -> bool:\n        if head is None or head.next is None:\n            return False\n        slowPointer = head\n        fastPointer = head.next\n        while slowPointer != fastPointer:\n            if fastPointer is None or fastPointer.next is None:\n                return False\n            fastPointer = fastPointer.next.next\n            slowPointer = slowPointer.next\n        return True","hash":"20e43ce43cd73efd5b4d8566004e8414b9c208f3cdec0610efadea6b5ee0d58a","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 07-01 Linked List Cycle.py"}]}],"sources":["solutions"]},"topic-day0702maxareaofisland":{"key":"topic-day0702maxareaofisland","number":null,"title":"Day 07 02 Max Area of Island","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 07-02 Max Area of Island.py","code":"class Solution:\n    def maxAreaOfIsland(self, grid: List[List[int]]) -> int:\n        LAND = 1\n        WATER = 0\n        maxArea = 0\n        numberOfRows = len(grid)\n        if numberOfRows == 0:\n            return maxArea\n        numberOfColumns = len(grid[0])\n        \n        def dfs(grid, row, column):\n            if row < 0 or row >= numberOfRows or column < 0 or column >= numberOfColumns or grid[row][column] != LAND:\n                return 0\n            else:\n                grid[row][column] = WATER\n                a = dfs(grid, row - 1, column)\n                b = dfs(grid, row + 1, column)\n                c = dfs(grid, row, column - 1)\n                d = dfs(grid, row, column + 1)\n                return a + b + c + d + 1\n        \n        for row in range(numberOfRows):\n            for column in range(numberOfColumns):\n                if grid[row][column] == LAND:\n                    area = dfs(grid, row, column)\n                    maxArea = max(area, maxArea)\n        return maxArea","hash":"1d4d4450f64482dce6e32f55e4dda40e2092084507184c987ef441df45128b99","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 07-02 Max Area of Island.py"}]}],"sources":["solutions"]},"topic-day0702mergetwosortedlists":{"key":"topic-day0702mergetwosortedlists","number":null,"title":"Day 07 02 Merge Two Sorted Lists","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 07-02 Merge Two Sorted Lists.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def mergeTwoLists(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:\n        dummyNode = ListNode('D')\n        currentNode = dummyNode\n        while l1 is not None and l2 is not None:\n            if l1.val <= l2.val:\n                currentNode.next = l1\n                l1 = l1.next\n            else:\n                currentNode.next = l2\n                l2 = l2.next\n            if currentNode and currentNode.next:\n                currentNode = currentNode.next\n        if l1 is None and l2 is not None:\n            currentNode.next = l2\n        elif l1 is not None and l2 is None:\n            currentNode.next = l1\n        else:\n            currentNode.next = None\n        return dummyNode.next","hash":"0d948a779e668ee2a324e5d36a9b7485f895e74ad917337102cd5baaa97d7686","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 07-02 Merge Two Sorted Lists.py"}]}],"sources":["solutions"]},"topic-day0703removelinkedlistelements":{"key":"topic-day0703removelinkedlistelements","number":null,"title":"Day 07 03 Remove Linked List Elements","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 07-03 Remove Linked List Elements.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def removeElements(self, head: ListNode, val: int) -> ListNode:\n        dummyNode = ListNode(-1)\n        dummyNode.next = head\n        currentNode = dummyNode\n        while currentNode is not None and currentNode.next is not None:\n            if currentNode.next.val == val:\n                currentNode.next = currentNode.next.next\n            else:\n                currentNode = currentNode.next\n        return dummyNode.next","hash":"4cc43dd6c18ca918215cb1ef65ef2714827e160007d089163efdcd649014be5d","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 07-03 Remove Linked List Elements.py"}]}],"sources":["solutions"]},"topic-day0801mergetwobinarytrees":{"key":"topic-day0801mergetwobinarytrees","number":null,"title":"Day 08 01 Merge Two Binary Trees","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 08-01 Merge Two Binary Trees.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def mergeTrees(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> Optional[TreeNode]:\n        if root1 is None:\n            return root2\n        if root2 is None:\n            return root1\n        root1.val += root2.val\n        root1.left = self.mergeTrees(root1.left, root2.left)\n        root1.right = self.mergeTrees(root1.right, root2.right)\n        return root1","hash":"3d31d74b579739f74ee3cf2811c6373bcdc8249baa3eb7d21db4a2ae4f6f377c","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 08-01 Merge Two Binary Trees.py"}]}],"sources":["solutions"]},"topic-day0801reverselinkedlist":{"key":"topic-day0801reverselinkedlist","number":null,"title":"Day 08 01 Reverse Linked List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 08-01 Reverse Linked List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def reverseList(self, head: ListNode) -> ListNode:\n        if head is None or head.next is None:\n            return head\n        tempNode = self.reverseList(head.next)\n        head.next.next = head\n        head.next = None\n        return tempNode","hash":"0095d0979bfbd2373ed4c35838559af4ead690d07d05f80f2aafa3c3ec49412a","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 08-01 Reverse Linked List.py"}]}],"sources":["solutions"]},"topic-day0802populatingnextrightpointersineachnode":{"key":"topic-day0802populatingnextrightpointersineachnode","number":null,"title":"Day 08 02 Populating Next Right Pointers in Each Node","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 08-02 Populating Next Right Pointers in Each Node.py","code":"\"\"\"\n# Definition for a Node.\nclass Node:\n    def __init__(self, val: int = 0, left: 'Node' = None, right: 'Node' = None, next: 'Node' = None):\n        self.val = val\n        self.left = left\n        self.right = right\n        self.next = next\n\"\"\"\n\nclass Solution:\n    def connect(self, root: 'Node') -> 'Node':\n        if root is None:\n            return root\n        leftmostNode = root\n        while leftmostNode.left:\n            head = leftmostNode\n            while head:\n                head.left.next = head.right\n                if head.next:\n                    head.right.next = head.next.left\n                head = head.next\n            leftmostNode = leftmostNode.left\n        return root","hash":"c4b6783b083de2622961fade415c9aadcbdac9b30cc536617e2799abfd257d97","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 08-02 Populating Next Right Pointers in Each Node.py"}]}],"sources":["solutions"]},"topic-day0802removeduplicatesfromsortedlist":{"key":"topic-day0802removeduplicatesfromsortedlist","number":null,"title":"Day 08 02 Remove Duplicates from Sorted List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 08-02 Remove Duplicates from Sorted List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def deleteDuplicates(self, head: ListNode) -> ListNode:\n        if head is None:\n            return head\n        currentNode = head\n        while currentNode and currentNode.next:\n            if currentNode.val == currentNode.next.val:\n                currentNode.next = currentNode.next.next\n            else:\n                currentNode = currentNode.next\n        return head","hash":"07e58d6335d813439770b3e83adeeedf7b3deee22e89679cad26b61adef98c03","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 08-02 Remove Duplicates from Sorted List.py"}]}],"sources":["solutions"]},"topic-day090101matrix":{"key":"topic-day090101matrix","number":null,"title":"Day 09 01 01 Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 09-01 01 Matrix.py","code":"class Solution:\n    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:\n        rows, cols = len(mat), len(mat[0])\n        dist = [[float('inf')] * cols for _ in range(rows)]\n        for i in range(rows):\n            for j in range(cols):\n                if mat[i][j] == 0:\n                    dist[i][j] = 0\n                else:\n                    if i > 0:\n                        dist[i][j] = min(dist[i][j], dist[i - 1][j] + 1)\n                    if j > 0:\n                        dist[i][j] = min(dist[i][j], dist[i][j - 1] + 1)\n        for i in range(rows - 1, -1, -1):\n            for j in range(cols - 1, -1, -1):\n                if i < rows - 1:\n                    dist[i][j] = min(dist[i][j], dist[i + 1][j] + 1)\n                if j < cols - 1:\n                    dist[i][j] = min(dist[i][j], dist[i][j + 1] + 1)\n        return dist","hash":"d2f73890653d293a4276fa308ff8c9aa1a3b53b948fd648094b16ab4f180ba1b","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 09-01 01 Matrix.py"}]}],"sources":["solutions"]},"topic-day0901validparentheses":{"key":"topic-day0901validparentheses","number":null,"title":"Day 09 01 Valid Parentheses","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 09-01 Valid Parentheses.py","code":"class Solution:\n    def isValid(self, s: str) -> bool:\n        stack = deque()\n        for c in s:\n            if c == '(' or c == '{' or c == '[':\n                stack.append(c)\n            elif c == ')':\n                if not stack or stack[-1] != '(':\n                    return False\n                else:\n                    stack.pop()\n            elif c == '}':\n                if not stack or stack[-1] != '{':\n                    return False\n                else:\n                    stack.pop()\n            elif c == ']':\n                if not stack or stack[-1] != '[':\n                    return False\n                else:\n                    stack.pop()\n        return len(stack) == 0","hash":"9d7c979293be1ec8ba8c7ab3c986a1bc75636d57a9f206e26b6ccd944ca4545c","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 09-01 Valid Parentheses.py"}]}],"sources":["solutions"]}});
